public class SpringFutureUtils {
    // *************************************** Converting to CompletableFuture ******************************************

    public static <T> CompletableFuture<T> createCompletableFuture(ValueSourceFuture<T> valueSource) {
        if (valueSource instanceof CompletableFutureBackedValueSourceFuture) {
            return ((CompletableFutureBackedValueSourceFuture<T>) valueSource).getWrappedFuture();
        } else {
            return new ValueSourceFutureBackedCompletableFuture<>(valueSource);
        }
    }

    public static <T> CompletableFuture<T> createCompletableFuture(ValueSource<T> valueSource) {
        if (valueSource instanceof CompletableFutureBackedValueSourceFuture) {
            return ((CompletableFutureBackedValueSourceFuture<T>) valueSource).getWrappedFuture();
        } else {
            return new ValueSourceBackedCompletableFuture<>(valueSource);
        }
    }

    /**
     * CompletableFuture that delegates all the work to ValueSourceFuture.
     */
    private static class ValueSourceFutureBackedCompletableFuture<T> extends FutureWrapper<T> implements CompletableFuture<T> {
        private ValueSourceFutureBackedCompletableFuture(ValueSourceFuture<T> valueSourceFuture) {
            super(valueSourceFuture);
        }

        @Override
        public T join() {
            try {
                return getWrappedFuture().get();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        protected ValueSourceFuture<T> getWrappedFuture() {
            return (ValueSourceFuture<T>) super.getWrappedFuture();
        }
    }


    /**
     * If we only get ValueSource we have to create a ValueSourceFuture. Here we wrap CompletableFuture
     * and use it for listener handling and value storage.
     */
    private static class ValueSourceBackedCompletableFuture<T> extends FutureWrapper<T> implements CompletableFuture<T> {
        private final ValueSource<T> valueSource;

        private ValueSourceBackedCompletableFuture(ValueSource<T> valueSource) {
            super(new CompletableFuture<>());
            this.valueSource = valueSource;
            valueSource.addCallbacks(value -> getWrappedFuture().complete(value), ex -> getWrappedFuture().completeExceptionally(ex));
        }


        @Override
        protected CompletableFuture<T> getWrappedFuture() {
            return (CompletableFuture<T>) super.getWrappedFuture();
        }

        @Override
        public boolean cancel(boolean mayInterruptIfRunning) {
            valueSource.cancel(mayInterruptIfRunning);
            return super.cancel(mayInterruptIfRunning);
        }

        private ValueSource<T> getValueSource() {
            return valueSource;
        }
    }

    // *************************************** Converting from CompletableFuture ******************************************

    public static <T> ValueSourceFuture<T> createValueSourceFuture(CompletableFuture<T> completableFuture) {
        if (completableFuture instanceof ValueSourceFutureBackedCompletableFuture) {
            return ((ValueSourceFutureBackedCompletableFuture<T>) completableFuture).getWrappedFuture();
        } else {
            return new CompletableFutureBackedValueSourceFuture<>(completableFuture);
        }
    }

    public static <T> ValueSource<T> createValueSource(CompletableFuture<T> completableFuture) {
        if (completableFuture instanceof ValueSourceBackedCompletableFuture) {
            return ((ValueSourceBackedCompletableFuture<T>) completableFuture).getValueSource();
        } else {
            return new CompletableFutureBackedValueSourceFuture<>(completableFuture);
        }
    }


    private static class CompletableFutureBackedValueSourceFuture<T> extends ValueSourceFuture<T> {
        private CompletableFutureBackedValueSourceFuture(CompletableFuture<T> wrappedFuture) {
            super(wrappedFuture);
        }

        @Override
        public void addCallbacks(Consumer<T> successCallback, Consumer<Throwable> failureCallback) {
            getWrappedFuture().whenComplete((value, ex) -> {
                if (ex != null) {
                    failureCallback.accept(ex);
                } else {
                    successCallback.accept(value);
                }
            });
        }

        @Override
        protected CompletableFuture<T> getWrappedFuture() {
            return (CompletableFuture<T>) super.getWrappedFuture();
        }
    }
}

