package net.javacrumbs.futureconverter.common.test.spring;

import net.javacrumbs.futureconverter.common.test.AbstractConverterTest;
import net.javacrumbs.futureconverter.common.test.ConvertedFutureTestHelper;
import net.javacrumbs.futureconverter.common.test.common.CommonConvertedFutureTestHelper;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SpringConvertedFutureTestHelper extends CommonConvertedFutureTestHelper implements ConvertedFutureTestHelper<CompletableFuture<String>> {
    private final AtomicReference<String> resultRef = new AtomicReference<>();
    private final AtomicReference<Throwable> exceptionRef = new AtomicReference<>();

    @Override
    public void waitForCalculationToFinish(CompletableFuture<String> convertedFuture) throws InterruptedException {
        final CountDownLatch latch = new CountDownLatch(1);
        convertedFuture.whenComplete((result, throwable) -> {
            resultRef.set(result);
            exceptionRef.set(throwable);
            latch.countDown();
        });
        latch.await(1, TimeUnit.SECONDS);
    }

    @Override
    public void verifyCallbackCalledWithCorrectValue() throws InterruptedException {
        waitForCallback();
        assertEquals(AbstractConverterTest.VALUE, resultRef.get());
    }

    @Override
    public void verifyCallbackCalledWithException(Exception exception) throws InterruptedException {
        waitForCallback();
        Throwable throwable = exceptionRef.get();
        assertTrue(throwable != null && throwable.getClass().equals(exception.getClass()));
    }

    @Override
    public void verifyCallbackCalledWithException(Class<? extends Exception> exceptionClass) throws InterruptedException {
        waitForCallback();
        Throwable throwable = exceptionRef.get();
        assertTrue(throwable != null && exceptionClass.isInstance(throwable));
    }

    @Override
    public void addCallbackTo(CompletableFuture<String> convertedFuture) {
        convertedFuture.whenComplete((result, throwable) -> {
            resultRef.set(result);
            exceptionRef.set(throwable);
            callbackCalled();
        });
    }
}

