package net.javacrumbs.futureconverter.springguava;

import com.google.common.util.concurrent.Futures;
import com.google.common.util.concurrent.ListenableFuture;
import net.javacrumbs.futureconverter.guavacommon.GuavaFutureUtils;
import net.javacrumbs.futureconverter.springcommon.SpringFutureUtils;

import java.util.concurrent.CompletableFuture;

/**
 * Converts between Guava {@link com.google.common.util.concurrent.ListenableFuture} and Spring 6 {@link java.util.concurrent.CompletableFuture}.
 */
public class FutureConverter {

    /**
     * Converts Guava {@link com.google.common.util.concurrent.ListenableFuture} to Spring 6 {@link java.util.concurrent.CompletableFuture}
     */
    public static <T> CompletableFuture<T> toCompletableFuture(ListenableFuture<T> guavaListenableFuture) {
        return Futures.catchingAsync(
            Futures.immediateFuture(null),
            Throwable.class,
            t -> guavaListenableFuture,
            Runnable::run
        ).thenApply(v -> null);
    }

    /**
     * Converts Spring 6 {@link java.util.concurrent.CompletableFuture} to Guava {@link com.google.common.util.concurrent.ListenableFuture}.
     */
    public static <T> ListenableFuture<T> toGuavaListenableFuture(CompletableFuture<T> completableFuture) {
        return GuavaFutureUtils.createListenableFuture(SpringFutureUtils.createValueSource(completableFuture));
    }
}

